// Event definitions for the Order aggregate
type OrderEvent =
  | { type: 'OrderStateChanged'; newState: string; changedAt: string }
  | { type: 'LineItemsModified'; items: LineItem[] }
  | { type: 'OrderStateChanged'; newState: string; changedAt: string; overrideBy?: string }

// applyEvent function — stores current state directly in DB after each event
async function applyEvent(state: OrderState, event: OrderEvent): Promise<OrderState> {
  const next = computeNextState(state, event);
  // Persist derived state for fast reads
  await db.query('UPDATE orders SET state = $1 WHERE id = $2', [next, state.id]);
  return next;
}

